package com.tecverse.app.service;

import com.tecverse.app.entity.ThematicReservation;
import com.tecverse.app.entity.ThematicSession;
import com.tecverse.app.repository.ThematicReservationRepository;
import com.tecverse.app.repository.ThematicSessionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;

@Service
public class ThematicReservationService {
    private final ThematicSessionRepository sessions; private final ThematicReservationRepository reservations;
    public ThematicReservationService(ThematicSessionRepository sessions,ThematicReservationRepository reservations){this.sessions=sessions;this.reservations=reservations;}
    public List<Map<String,Object>> publicSessions(Long userId){return sessions.findByPublishedTrueAndActiveTrueOrderBySessionDateAscIdAsc().stream().map(s->{boolean available=reservations.countBySessionIdAndStatus(s.getId(),"CONFIRMED")<s.getTotalCapacity()-s.getReservedSeats();return Map.<String,Object>of("id",s.getId(),"title",s.getTitle(),"description",Objects.toString(s.getDescription(),""),"date",displayDate(s.getSessionDate()),"time",displayTime(s.getTimeLabel()),"availability",available?"Available":"Not Available","reserved",reservations.existsByRegistrationIdAndSessionIdAndStatus(userId,s.getId(),"CONFIRMED"));}).toList();}
    @Transactional public void reserve(Long userId,Long sessionId){ThematicSession s=sessions.findByIdForUpdate(sessionId).orElseThrow(()->new IllegalArgumentException("Session not found."));if(!s.isPublished()||!s.isActive())throw new IllegalArgumentException("This session is not open for reservations.");ThematicReservation r=reservations.findByRegistrationIdAndSessionId(userId,sessionId).orElse(null);if(r!=null&&"CONFIRMED".equals(r.getStatus()))throw new IllegalArgumentException("You have already reserved this session.");if(reservations.countBySessionIdAndStatus(sessionId,"CONFIRMED")>=s.getTotalCapacity()-s.getReservedSeats())throw new IllegalArgumentException("This session is fully booked. Refresh the list to see current availability.");if(r==null){r=new ThematicReservation();r.setRegistrationId(userId);r.setSessionId(sessionId);}else r.setStatus("CONFIRMED");reservations.save(r);}
    @Transactional public void cancel(Long userId,Long reservationId){ThematicReservation r=reservations.findOwned(reservationId,userId).orElseThrow(()->new IllegalArgumentException("Reservation not found."));if(!"CONFIRMED".equals(r.getStatus()))throw new IllegalArgumentException("This reservation is already cancelled.");r.setStatus("CANCELLED");}
    public List<Map<String,Object>> myReservations(Long userId){return reservations.findByRegistrationIdAndStatus(userId,"CONFIRMED").stream().map(r->sessions.findById(r.getSessionId()).map(s->Map.<String,Object>of("id",r.getId(),"sessionTitle",s.getTitle(),"date",displayDate(s.getSessionDate()),"time",displayTime(s.getTimeLabel()))).orElse(null)).filter(Objects::nonNull).toList();}
    public List<Map<String,Object>> adminSessions(){return sessions.findAllByOrderBySessionDateAscIdAsc().stream().map(s->{long booked=reservations.countBySessionIdAndStatus(s.getId(),"CONFIRMED");Map<String,Object> item=new LinkedHashMap<>();item.put("id",s.getId());item.put("title",s.getTitle());item.put("description",Objects.toString(s.getDescription(),""));item.put("date",Objects.toString(s.getSessionDate(),""));item.put("time",Objects.toString(s.getTimeLabel(),""));item.put("totalCapacity",s.getTotalCapacity());item.put("reservedSeats",s.getReservedSeats());item.put("generalCapacity",s.getTotalCapacity()-s.getReservedSeats());item.put("confirmed",booked);item.put("remaining",s.getTotalCapacity()-s.getReservedSeats()-booked);item.put("published",s.isPublished());item.put("active",s.isActive());return item;}).toList();}
    @Transactional public ThematicSession save(Long id,Map<String,Object> form){ThematicSession s=id==null?new ThematicSession():sessions.findByIdForUpdate(id).orElseThrow(()->new IllegalArgumentException("Session not found."));String title=Objects.toString(form.get("title"),"").trim(),description=Objects.toString(form.get("description"),""),date=Objects.toString(form.get("date"),""),time=Objects.toString(form.get("time"),"");int capacity=number(form.get("totalCapacity"),300),reserved=number(form.get("reservedSeats"),10);if(title.isBlank()||title.length()>180||description.length()>3000||capacity<1||reserved<0||reserved>=capacity)throw new IllegalArgumentException("Enter a title, valid session details and capacity values; reserved seats must be less than total capacity.");try{if(!date.isBlank())date=LocalDate.parse(date).toString();if(!time.isBlank())time=LocalTime.parse(time).format(DateTimeFormatter.ofPattern("HH:mm"));}catch(java.time.format.DateTimeParseException invalid){throw new IllegalArgumentException("Enter the date as YYYY-MM-DD and time as HH:MM.");}long confirmed=s.getId()==null?0:reservations.countBySessionIdAndStatus(s.getId(),"CONFIRMED");if(capacity-reserved<confirmed)throw new IllegalArgumentException("General capacity cannot be reduced below confirmed reservations.");s.setTitle(title);s.setDescription(description);s.setSessionDate(date);s.setTimeLabel(time);s.setTotalCapacity(capacity);s.setReservedSeats(reserved);s.setPublished(Boolean.parseBoolean(Objects.toString(form.get("published"),"false")));s.setActive(Boolean.parseBoolean(Objects.toString(form.get("active"),"true")));return sessions.save(s);}
    @Transactional public void delete(Long id){if(reservations.countBySessionId(id)>0)throw new IllegalArgumentException("Sessions with reservation history cannot be deleted. Set the session inactive to archive it.");sessions.deleteById(id);}
    private static int number(Object value,int fallback){try{return Integer.parseInt(Objects.toString(value,""));}catch(NumberFormatException e){return fallback;}}
    private static String displayDate(String value){try{return value==null||value.isBlank()?"":LocalDate.parse(value).format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.ENGLISH));}catch(java.time.format.DateTimeParseException ignored){return Objects.toString(value,"");}}
    private static String displayTime(String value){try{return value==null||value.isBlank()?"":LocalTime.parse(value).format(DateTimeFormatter.ofPattern("h:mm a",Locale.ENGLISH));}catch(java.time.format.DateTimeParseException ignored){return Objects.toString(value,"");}}
}
